export async function pruneSearchDocuments(
  orgId: OrgId,
  keep: ReadonlySet<string>,
): Promise<number> {
  const db = getDb();
  const rows = db
    .select({
      id: searchIndex.id,
      subjectKind: searchIndex.subjectKind,
      subjectId: searchIndex.subjectId,
    })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .all();

  const seen = new Set<string>();
  const doomed: string[] = [];
