export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const keep = new Set<string>();

    const track = (kind: SearchSubjectKind, id: string, indexed: boolean) => {
      if (indexed) keep.add(searchRepo.searchDocumentKey(kind, id));
    };

    let projectCursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
        includeArchived: true,
      });

      for (const project of projects.items) {
        try {
          track("project", project.id, await indexProject(orgId, project));
          result.processed += 1;
        } catch (error) {
          // Leave whatever is indexed for it alone rather than guess.
          keep.add(searchRepo.searchDocumentKey("project", project.id));
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      projectCursor = projects.nextCursor;
    } while (projectCursor);

    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
        includeArchived: true,
      });

      for (const issue of issues.items) {
        let comments: readonly Comment[] = [];
        try {
          track("issue", issue.id, await indexIssue(orgId, issue));
          result.processed += 1;

          comments = await commentRepo.listCommentsForIssue(orgId, issue.id, {
            includeArchived: true,
          });

          for (const comment of comments) {
            track("comment", comment.id, await indexComment(orgId, comment));
            result.processed += 1;
          }
        } catch (error) {
          keep.add(searchRepo.searchDocumentKey("issue", issue.id));
          for (const comment of comments) {
            keep.add(searchRepo.searchDocumentKey("comment", comment.id));
          }
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      issueCursor = issues.nextCursor;
    } while (issueCursor);

    await searchRepo.pruneSearchDocuments(orgId, keep);
  });
}
