import { beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/rate-limit", () => ({ consumeRateLimit: async () => ({ allowed: true, remaining: 1, resetAt: "x" }) }));
import { setupTestDb, resetTestDb, seedTwoTenants } from "./helpers/db";
import { makeActor, ORG_A, ORG_B, ALICE } from "./helpers/factories";
import * as searchService from "@/server/services/search-service";
import * as projectService from "@/server/services/project-service";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { getDb, users, organizations } from "@/server/db";
import { eq } from "drizzle-orm";

const owner = makeActor({ role: "owner" });
let alice: any;
const q = (s: string, kinds: any[] = ["issue", "comment", "project"], orgId = ORG_A, actor = owner) =>
  searchService.search(actor, { orgId, q: s, kinds, limit: 100, cursor: null } as any);

async function mkProject(name: string, orgId = ORG_A) {
  return projectRepo.insertProject({ orgId, name, slug: name.toLowerCase(), key: name.slice(0, 3).toUpperCase(), description: null, visibility: "public", leadId: null, color: "#000000", targetDate: null } as any);
}

beforeAll(async () => {
  await setupTestDb();
  await resetTestDb();
  const { orgA } = await seedTwoTenants();
  getDb().insert(users).values({ id: ALICE, email: "a@x.com", name: "A", passwordHash: "x", timezone: "UTC", createdAt: "2026-01-01T00:00:00.000Z", updatedAt: "2026-01-01T00:00:00.000Z" }).onConflictDoNothing().run();
  getDb().update(organizations).set({ plan: "enterprise" } as any).run();
  searchService.registerSearchListeners();
});

describe("scratch", () => {
  it("lifecycle", async () => {
    const p = await mkProject("Alpha");
    await searchService.indexProject(ORG_A, p);
    const i1 = await issueService.createIssue(owner, { orgId: ORG_A, projectId: p.id, title: "kw issue one", description: null, status: "todo", priority: "none", assigneeId: null, parentId: null, estimate: null, dueAt: null, labelIds: [] } as any);
    const i2 = await issueService.createIssue(owner, { orgId: ORG_A, projectId: p.id, title: "kw issue two", description: null, status: "todo", priority: "none", assigneeId: null, parentId: null, estimate: null, dueAt: null, labelIds: [] } as any);
    const c1 = await commentService.createComment(owner, { orgId: ORG_A, issueId: i1.id, body: "kw comment on one", parentId: null, mentionedUserIds: [] } as any);
    const c2 = await commentService.createComment(owner, { orgId: ORG_A, issueId: i2.id, body: "kw comment on two", parentId: null, mentionedUserIds: [] } as any);
    expect((await q("kw")).total).toBe(4);
    await issueService.archiveIssue(owner, ORG_A, i1.id);
    expect((await q("kw")).total).toBe(2);
    await projectService.archiveProject(owner, { orgId: ORG_A, projectId: p.id, archiveIssues: false } as any);
    expect((await q("kw")).total).toBe(0);
    await commentService.createComment(owner, { orgId: ORG_A, issueId: i2.id, body: "kw later", parentId: null, mentionedUserIds: [] } as any);
    await issueService.updateIssue(owner, { orgId: ORG_A, issueId: i2.id, title: "kw edited" } as any);
    expect((await q("kw")).total).toBe(0);
    expect(await searchRepo.countIndexed(ORG_A)).toBe(0);
    await projectService.restoreProject(owner, ORG_A, p.id);
    const r = await q("kw");
    expect(r.items.map((x) => x.id).sort()).toEqual([i2.id, c2.id, (await commentRepo.listCommentsForIssue(ORG_A, i2.id)).find((c) => c.body === "kw later")!.id].sort());
    expect((await q("Alpha", ["project"])).total).toBe(1);
    void c1;
  });

  it("rebuild", async () => {
    const p = await mkProject("Big");
    for (let n = 0; n < 230; n++) {
      const iss = await issueRepo.insertIssue({ orgId: ORG_A, projectId: p.id, title: `bigkw ${n}`, description: null, status: "todo", priority: "none", assigneeId: null, parentId: null, estimate: null, dueAt: null, labelIds: [] } as any, ALICE, n + 1);
      await commentRepo.insertComment({ orgId: ORG_A, issueId: iss.id, body: `bigkw c ${n}`, parentId: null, mentionedUserIds: [] } as any, ALICE);
    }
    const pb = await mkProject("Other", ORG_B);
    await searchService.indexProject(ORG_B, pb);
    await searchRepo.upsertSearchDocument(ORG_A, "comment", "ghost", "bigkw ghost", null);
    const before = await searchRepo.countIndexed(ORG_A);
    const res = await runSearchReindexJob(ORG_A);
    console.log(res, before);
    const hits = await q("bigkw", ["issue", "comment"]);
    expect(hits.total).toBe(460);
    expect(await searchRepo.countIndexed(ORG_B)).toBe(1);
    const n1 = await searchRepo.countIndexed(ORG_A);
    await runSearchReindexJob(ORG_A);
    expect(await searchRepo.countIndexed(ORG_A)).toBe(n1);
    console.log(n1);
  });
});
